/* Small, contextual dialogs; the server still validates every farm request. */
function simpleBedReason(p,code){
 const view=bedPresentation(p);if(view.preview)return 'Это демонстрация посадок. Фактическое состояние уточнит садовник.';
 p=view;
 if(code==='harvest'&&p.growing_state!=='harvest_ready')return ['planted','growing'].includes(p.growing_state)?'Урожай ещё растёт. Садовник подтвердит, когда его можно собирать.':'На грядке пока нет созревшего урожая.';
 const s=opsData?.services.find(s=>s.code===code);if(!s?.enabled||s.price_kopecks===null)return 'Услуга пока недоступна';
 if((opsData?.orders||[]).some(o=>Number(o.plot_id)===Number(p.id)&&!['done','cancelled'].includes(o.status)))return 'Сначала дождитесь текущей работы';
 const plan=opsData?.plans.find(x=>Number(x.plot_id)===Number(p.id));
 const last=(opsData?.orders||[]).filter(o=>Number(o.plot_id)===Number(p.id)&&o.service_code===code&&o.status==='done'&&!o.is_simulation).sort((a,b)=>Date.parse(b.finished_at)-Date.parse(a.finished_at))[0];
 return serviceReason(code,p,plan,last?.finished_at);
}
function simpleGardener(){return `<svg class="simple-gardener" viewBox="0 0 240 190" aria-hidden="true"><ellipse cx="120" cy="177" rx="75" ry="9" fill="#50763b22"/><path d="M67 169q-3-62 53-62t53 62" fill="#82b756"/><path d="M91 119v50h59v-50l-15-6v30h-30v-30Z" fill="#447865"/><circle cx="120" cy="75" r="39" fill="#f1c58c"/><path d="M80 67q-1-36 42-35t37 38l-16-20-47 6Z" fill="#765236"/><ellipse cx="120" cy="43" rx="70" ry="13" fill="#d5aa58"/><path d="M84 42l9-28q27-13 54 0l10 28" fill="#efcb78"/><path d="M91 30h61" stroke="#84a353" stroke-width="9"/><circle cx="106" cy="76" r="3.5" fill="#4c4435"/><circle cx="135" cy="76" r="3.5" fill="#4c4435"/><path d="M107 92q13 13 27 0" fill="none" stroke="#975c47" stroke-width="4" stroke-linecap="round"/><circle cx="95" cy="88" r="7" fill="#e8a17b" opacity=".6"/><circle cx="146" cy="88" r="7" fill="#e8a17b" opacity=".6"/><path d="M63 153l-13-25M177 150l14-28" stroke="#edc18b" stroke-width="17" stroke-linecap="round"/><path d="M190 128v-58" stroke="#9b7745" stroke-width="7"/><path d="M178 70h24l-4 22h-16Z" fill="#a2bbc0"/><circle cx="105" cy="148" r="3" fill="#f7dd85"/><circle cx="135" cy="148" r="3" fill="#f7dd85"/></svg>`}
function simpleBedCare(id){const p=myPlots().find(p=>Number(p.id)===Number(id));if(!p)return;
 modalForm('Что поручим садовнику?',`${simpleGardener()}<div class="simple-care-grid">${[['water','💧','Полить'],['feed','🌿','Подкормить'],['weed','🌾','Прополоть'],['loosen','🪏','Разрыхлить']].map(([code,icon,name])=>{const reason=simpleBedReason(p,code),s=opsData?.services.find(x=>x.code===code);return `<button type="button" ${reason?'disabled':''} title="${esc(reason||name)}" onclick="simpleBedWork(${id},'${code}')"><span>${icon}</span><b>${name}</b><small>${esc(reason||money(s.price_kopecks)+' · ~'+s.duration_minutes+' мин.')}</small></button>`}).join('')}</div>`,()=>{});
}
function simpleBedWork(id,code){const p=myPlots().find(p=>Number(p.id)===Number(id));if(!p)return;const reason=simpleBedReason(p,code);
 if(reason){modalForm(code==='harvest'?'Сбор пока недоступен':'Пока не получится',`<div class="simple-action-symbol">${code==='harvest'?'🧺':'🌱'}</div><p>${esc(reason)}</p><button type="button" class="btn" onclick="modal.close()">Понятно</button>`,()=>{});return}
 const s=opsData.services.find(x=>x.code===code),key=crypto.randomUUID(),cycles=(seasonData?.cycles||[]).filter(c=>Number(c.plot_id)===Number(id)&&c.approved&&!c.ended_on),destination=typeof hasStorage==='function'&&hasStorage()?'storage':'home';
 formAsync(code==='harvest'?'Отправить садовника на сбор?':'Поручить: '+s.title+'?',`<div class="simple-action-symbol">${code==='harvest'?'🧺':'👩‍🌾'}</div><p>Грядка №${id} · <b>${esc(s.title)}</b></p><p><b>${money(s.price_kopecks)}</b> · работа ~${s.duration_minutes} мин.</p>${code==='harvest'?`<p>После сбора: ${destination==='storage'?'на ваш склад':'подготовка к доставке домой'}. Доставка согласуется отдельно.</p>`:''}${cycles.length>1?`<label>Какие посадки?<select name="cycle" required>${cycles.map(c=>`<option value="${esc(c.id)}">${esc(c.crop)}</option>`).join('')}</select></label>`:''}<p class="simple-note">Заявка без списания. Срок и демооплату подтвердите после согласования.</p><button class="btn">Да, отправить задание</button>`,async f=>{
  await api('order-create',{plot:id,service:code,key,cycle:f.get('cycle')||null,destination:code==='harvest'?destination:undefined});await loadOperations();
  modalForm('Задание отправлено!',`<div class="simple-action-symbol">✓</div><p>${esc(s.title)} · грядка №${id}</p><button type="button" class="btn" onclick="modal.close();openFarmBed(${id},'overview')">К грядке</button>`,()=>{});
 });
}
async function simpleBedCamera(id){
 modalForm('Камера грядки',`<div class="simple-camera-live" role="status">📹 Подключаем камеру…</div>${simpleCameraButtons(id)}`,()=>{});
 const dialog=document.querySelector('.simple-camera-live'),uid=account?.id;
 try{const data=await api('camera?id='+id);if(account?.id!==uid||!dialog?.isConnected)return;
 if(data.url){dialog.innerHTML='<video controls playsinline aria-label="Прямая трансляция грядки"></video>';const video=dialog.querySelector('video');video.src=data.url;video.onerror=()=>toast('Не удалось открыть трансляцию. Попробуйте позже.')}else dialog.innerHTML='<span>📹</span><p>Камера пока не подключена</p>';
 }catch(e){if(dialog?.isConnected)dialog.textContent=e.message}
}
function simpleCameraButtons(id){return `<div class="simple-camera-grid"><button type="button" onclick="simpleCameraArchive(${id})"><span>🎞️</span><b>Архив</b></button><button type="button" onclick="simpleCameraRequest(${id},'timelapse')"><span>🌱</span><b>Таймлапс</b></button><button type="button" onclick="simpleCameraRequest(${id},'archive')"><span>☁️</span><b>Хранение</b></button></div>`}
function simpleCameraArchive(id){modalForm('Архив камеры',`<div class="simple-action-symbol">🎞️</div><p>Записи ещё не подключены к этой грядке.</p><button type="button" class="btn" onclick="simpleCameraRequest(${id},'archive')">Настроить хранение</button><button type="button" class="btn light" onclick="simpleBedCamera(${id})">← К камере</button>`,()=>{})}
function simpleCameraRequest(id,kind){const key=crypto.randomUUID(),archive=kind==='archive';formAsync(archive?'Хранение записей':'Таймлапс роста',`<div class="simple-action-symbol">${archive?'☁️':'🌱'}</div>${archive?'<label>Хранить записи<select name="days"><option value="7">7 дней</option><option value="14">14 дней</option><option value="30">30 дней</option></select></label>':'<p>Попросим собрать короткий ролик роста из записей вашей камеры.</p>'}<p class="simple-note">Ферма подтвердит подключение и цену. Сейчас без списания.</p><button class="btn">Отправить запрос</button>`,async f=>{await api('life-request',{key,plot:id,kind,details:archive?'Подключить архив камеры на '+f.get('days')+' дней':'Подготовить таймлапс роста грядки из доступных записей'});await loadLife();modalForm('Запрос отправлен',`<div class="simple-action-symbol">✓</div><p>Ферма сообщит об условиях подключения.</p><button type="button" class="btn" onclick="simpleBedCamera(${id})">К камере</button>`,()=>{})})}
// The same small dialogs also serve shortcuts inside improvement/history screens.
gameOpenBed=function(id,tab){closeFieldMenu();bedJourneyOpen(id,tab)};
